def transform(grid):
    out=[row[:] for row in grid]
    r,c=next((r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1)
    tr,tc=next((r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2)
    dr=1 if tr>r else -1; dc=1 if tc>c else -1
    # Continue diagonal toward the marker, stopping one short of whichever
    # marker axis is closer; then continue along the remaining axis.
    if abs(tr-r)<=abs(tc-c):
        while r!=tr-dr and c!=tc:
            r+=dr; c+=dc
            if out[r][c]==0: out[r][c]=3
        while c!=tc-dc:
            c+=dc
            if out[r][c]==0: out[r][c]=3
    else:
        while c!=tc-dc and r!=tr:
            r+=dr; c+=dc
            if out[r][c]==0: out[r][c]=3
        while r!=tr-dr:
            r+=dr
            if out[r][c]==0: out[r][c]=3
    return out", "exit_code": 0, "error": null}
